        {'version': '3.48.0', 'channel': 'stable'},
        {'version': '3.47.9', 'channel': 'beta'},
        {'version': '3.47.4', 'channel': 'stable'},
        {'version': '3.47.1', 'channel': 'stable'},
      ],
    }),
  );
  return path;
}

