        File('${sdk.path}/$v/bin/flutter').writeAsStringSync(v);
      }
      runSlot(['flip', '${sdk.path}/3.47.4', '${sdk.path}/current']);
      expect(Link('${sdk.path}/current').targetSync(), '${sdk.path}/3.47.4');
