      expect(Link('${sdk.path}/current').targetSync(), '${sdk.path}/3.48.0');
      expect(
        File('${sdk.path}/3.47.4/bin/flutter').existsSync(),
        isTrue,
        reason: 'flip must never delete the version it swaps away from',
      );
